<script setup>
import { computed,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { Database,Cpu,ScanLine,Download,Info,ArrowRight,Activity } from '@lucide/vue'
import Chart from '../components/Chart.vue'
import { api,fmt,cityNames,baseChart } from '../lib/api'
const props=defineProps({meta:Object})
const meta=ref(null),registry=ref(null),error=ref(''),forecastError=ref(''),busy=ref(false)
const city=ref('beijing'),stationId=ref('1001A'),time=ref('2025-12-30T12:00'),year=ref('2025'),model=ref('best')
const snapshot=ref(null),history=ref(null),trend=ref(null),forecast=ref(null)
const weather=ref('wind_speed_10m'),split=ref('test'),scope=ref('beijing')
const names={best:'按验证集择优',rf:'Spark 随机森林',tcn72:'CUDA 时序卷积 TCN',persistence:'当前值持续基线'}
const weatherInfo={wind_speed_10m:['风速','m/s'],temperature_2m:['气温','°C'],relative_humidity_2m:['相对湿度','%'],surface_pressure:['气压','hPa'],precipitation:['降水','mm'],wind_direction_10m:['风向','°']}
let timer,request=0
const stations=computed(()=>(meta.value?.stations||[]).filter(s=>city.value==='all'||s.city_id===city.value))
const selected=computed(()=>meta.value?.stations.find(s=>s.station_id===stationId.value))
const gpu=computed(()=>registry.value?.gpu)
const phases={spark_prepare:'Spark 清洗、融合与 72 小时特征构建',spark_rf:'Spark 随机森林训练与评估',cuda_training:'CUDA 时序模型训练',publishing:'模型已完成，正在生成站点观测与预测查询索引',complete:'已完成'}
const preparation=computed(()=>phases[meta.value?.training?.phase]||'HDFS 原始数据入库')
const runs=computed(()=>Object.values(registry.value?.runs||{}))
function metric(id,h,variant){return runs.value.find(r=>r.model===id&&r.horizon===h&&(variant?r.variant===variant:r.variant!=='instant_weather'))?.metrics.find(m=>m.split===split.value&&m.scope===scope.value)}
async function setup(){
  try{
    const [m,r]=await Promise.all([api('stations/meta'),api('stations/models')]);meta.value=m;registry.value=r
    if(m.ready&&!snapshot.value)await load()
  }catch(e){error.value=e.message}
}
async function load(){
  if(!meta.value?.ready)return
  const id=++request;busy.value=true;error.value='';forecastError.value=''
  const values=await Promise.allSettled([api('stations/snapshot',{time:time.value,city:city.value}),api('stations/history',{station_id:stationId.value,end:time.value,hours:72}),api('stations/trend',{station_id:stationId.value,year:year.value}),api('stations/forecast',{station_id:stationId.value,time:time.value,model:model.value})])
  if(id!==request)return
  ;[snapshot,history,trend,forecast].forEach((target,i)=>{if(values[i].status==='fulfilled')target.value=values[i].value;else{target.value=null;if(i===3)forecastError.value=values[i].reason.message;else error.value=values[i].reason.message}})
  busy.value=false
}
onMounted(async()=>{await setup();timer=setInterval(()=>{if(!meta.value?.ready)setup()},15000)})
onBeforeUnmount(()=>clearInterval(timer))
watch(city,()=>{if(!stations.value.some(s=>s.station_id===stationId.value))stationId.value=stations.value[0]?.station_id||'1001A';else load()})
watch(stationId,load)
const mapOption=computed(()=>{
  const center=props.meta.cities.find(c=>c.id===city.value)
  return {tooltip:{formatter:p=>`${p.data.name}<br/>PM₂.₅ ${fmt(p.value[2])} μg/m³`},geo:{map:'bth-region',roam:true,layoutCenter:['47%','49%'],layoutSize:'95%',zoom:center?3.2:1,center:center?[center.longitude,center.latitude]:undefined,scaleLimit:{min:.6,max:15},itemStyle:{areaColor:'#eff3e9',borderColor:'#d2dccd'},emphasis:{disabled:true}},visualMap:{show:false,dimension:2,min:0,max:150,inRange:{color:['#4a987a','#bcc179','#d8ac60','#bc6551']}},series:[{type:'scatter',coordinateSystem:'geo',data:(snapshot.value?.stations||[]).filter(s=>s.longitude!=null&&s.latitude!=null&&s.pm25!=null).map(s=>({name:`${s.station_id} ${s.name}`,station_id:s.station_id,value:[s.longitude,s.latitude,s.pm25],symbolSize:s.station_id===stationId.value?15:9,itemStyle:{borderColor:s.station_id===stationId.value?'#244d3e':'#fff',borderWidth:s.station_id===stationId.value?2.5:1.2}})),label:{show:true,position:'right',formatter:p=>p.data.station_id,color:'#52694d',fontSize:10},labelLayout:{hideOverlap:true}}]}
})
const forecastOption=computed(()=>{
  const f=forecast.value;if(!f)return {...baseChart}
  const n=f.history.length,times=[...f.history.map(p=>p.ts),...f.points.map(p=>p.target)]
  const extend=key=>[...Array(n-1).fill(null),f.current,...f.points.map(p=>p[key])]
  return {...baseChart,grid:{...baseChart.grid,bottom:55},xAxis:{...baseChart.xAxis,type:'category',data:times,boundaryGap:false,axisLabel:{formatter:v=>v.slice(5,16),color:'#839088'}},dataZoom:[{type:'inside',start:65,end:100},{type:'slider',start:65,end:100,height:13,bottom:0,borderColor:'transparent'}],series:[{name:'历史观测',type:'line',showSymbol:false,data:[...f.history.map(p=>p.pm25),...Array(6).fill(null)],lineStyle:{width:2,color:'#719083'},itemStyle:{color:'#719083'}},...['rf','tcn72','actual','baseline'].map((k,i)=>({name:['Spark 随机森林','CUDA TCN','后续真实值','持续基线'][i],type:'line',data:extend(k),showSymbol:k!=='baseline',symbolSize:5,lineStyle:{width:i===1?2.7:1.6,type:i>=2?'dashed':'solid'},itemStyle:{color:['#d29a59','#176e59','#7198a4','#abb1a4'][i]}}))]}
})
const weatherOption=computed(()=>({...baseChart,xAxis:{...baseChart.xAxis,type:'category',data:history.value?.points.map(p=>p.ts)||[],boundaryGap:false,axisLabel:{formatter:v=>v.slice(5,16),color:'#839088'}},yAxis:{...baseChart.yAxis,name:weatherInfo[weather.value][1],nameTextStyle:{color:'#89948b'}},series:[{type:weather.value==='precipitation'?'bar':'line',showSymbol:false,data:history.value?.points.map(p=>p[weather.value])||[],lineStyle:{width:2},itemStyle:{color:'#6e9a82'},areaStyle:{color:'#176e5910'}}]}))
const trendOption=computed(()=>({...baseChart,xAxis:{...baseChart.xAxis,type:'category',data:trend.value?.points.map(p=>p.date)||[],boundaryGap:false,axisLabel:{formatter:v=>v.slice(5),color:'#839088'}},series:[{name:'站点日均 PM₂.₅',type:'line',showSymbol:false,data:trend.value?.points.map(p=>p.pm25)||[],lineStyle:{color:'#176e59',width:2},itemStyle:{color:'#176e59'}}]}))
const errorOption=computed(()=>({...baseChart,yAxis:{...baseChart.yAxis,name:'RMSE · μg/m³'},xAxis:{...baseChart.xAxis,type:'category',data:['+1 h','+2 h','+3 h','+4 h','+5 h','+6 h']},legend:{bottom:0,textStyle:{fontSize:10,color:'#74836d'}},grid:{...baseChart.grid,bottom:50},series:['persistence','rf','tcn72'].map((id,i)=>({name:names[id],type:'line',symbolSize:5,data:Array.from({length:6},(_,h)=>metric(id,h+1)?.rmse),lineStyle:{width:id==='tcn72'?2.5:1.5,type:id==='persistence'?'dashed':'solid'},itemStyle:{color:['#adb5a5','#d29a59','#176e59'][i]}}))}))
const ablationOption=computed(()=>({...baseChart,yAxis:{...baseChart.yAxis,name:'RMSE · μg/m³'},xAxis:{...baseChart.xAxis,type:'category',data:['RF 当前气象','RF 气象历史','CUDA TCN 72h'],axisLabel:{fontSize:10,interval:0}},series:[{type:'bar',barWidth:'32%',label:{show:true,position:'top',formatter:p=>fmt(p.value,2),color:'#65785c'},data:[metric('rf',6,'instant_weather')?.rmse,metric('rf',6,'history72')?.rmse,metric('tcn72',6)?.rmse].map((value,i)=>({value,itemStyle:{color:['#becbb0','#d2a369','#176e59'][i],borderRadius:[4,4,0,0]}}))}]}))
const trainingOption=computed(()=>({...baseChart,xAxis:{...baseChart.xAxis,type:'category',name:'Epoch',data:gpu.value?.epochs.map(e=>e.epoch)||[]},yAxis:{...baseChart.yAxis,name:'验证集 +6h RMSE'},series:[{type:'line',data:gpu.value?.epochs.map(e=>e.validation_beijing_h6_rmse)||[],symbolSize:5,lineStyle:{width:2},itemStyle:{color:'#176e59'}}]}))
function mapSelect(event){if(event.data?.station_id)stationId.value=event.data.station_id}
function download(){if(!forecast.value)return;const f=forecast.value;const table=[['站点','预测起点','目标时刻','时长','Spark随机森林','CUDA TCN','真实值','持续基线'],...f.points.map(p=>[stationId.value,p.origin,p.target,p.horizon,p.rf,p.tcn72,p.actual??'',p.baseline])];const url=URL.createObjectURL(new Blob(['\ufeff'+table.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`station_${stationId.value}_forecast.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template>
  <div v-if="error" class="error-box" role="alert">{{ error }}</div>
  <div v-if="!meta" class="page-loader"><span class="spinner"></span>正在连接站点实验…</div>
  <section v-else-if="!meta.ready" class="panel"><h2>站点数据与 GPU 模型正在准备</h2><p class="station-copy">全国逐站小时原始记录 → Spark 清洗与 72 小时特征 → CPU / CUDA 模型 → 同条件独立评估。</p><p class="station-copy">已下载 {{ fmt(meta.download.hourly_files,0) }} 份原始小时文件。当前阶段：{{ preparation }}。</p><p v-if="meta.training.current" class="station-copy">CPU 模型进度：{{ meta.training.completed }} / {{ meta.training.total }}。</p><p v-if="meta.gpu_training?.device" class="station-copy">CUDA 设备：{{ meta.gpu_training.device }} · {{ meta.gpu_training.phase==='complete'?'训练完成':`Epoch ${meta.gpu_training.epoch || 0} / ${meta.gpu_training.max_epochs || 12}` }}。</p></section>
  <template v-else>
    <section class="forecast-banner"><div class="forecast-emblem"><Cpu :size="25" /></div><div><h3>站点级观测 × 72 小时气象历史 × GPU 时序模型</h3><p>2022—2023 训练 · 2024 验证 · 2025 独立测试；原 2015—2025 城市版保留在其他页面。</p></div><span class="outline-tag">Spark + CUDA</span></section>
    <section class="kpi-grid"><article class="kpi-card featured"><div class="kpi-label">历史监测站点<Database :size="15" /></div><div class="kpi-number">{{ fmt(meta.summary.stations,0) }}<small>个</small></div><div class="kpi-bottom">含停运与新增站点</div></article><article class="kpi-card"><div class="kpi-label">有效站点小时 PM₂.₅</div><div class="kpi-number">{{ fmt(meta.summary.valid_pm25/10000,1) }}<small>万条</small></div><div class="kpi-bottom">网格 {{ fmt(meta.summary.grid_hours,0) }} 行</div></article><article class="kpi-card"><div class="kpi-label">历史气象输入</div><div class="kpi-number">72<small>小时</small></div><div class="kpi-bottom">RF {{ meta.summary.feature_count }} 特征 · TCN 完整序列</div></article><article class="kpi-card"><div class="kpi-label">实测 GPU 峰值利用率<Cpu :size="15" /></div><div class="kpi-number">{{ fmt(gpu?.peak_gpu_util_percent,0) }}<small>%</small></div><div class="kpi-bottom">CUDA 训练证据见下方</div></article></section>
    <section class="panel"><div class="station-controls"><label class="form-field">观测城市<select v-model="city" aria-label="站点城市"><option value="all">全部六城</option><option v-for="(name,id) in cityNames" :value="id">{{ name }}</option></select></label><label class="form-field">监测站点<select v-model="stationId" aria-label="监测站点"><option v-for="s in stations" :value="s.station_id">{{ s.station_id }} · {{ s.name }}</option></select></label><label class="form-field">预测起点 · 北京时间<input type="datetime-local" v-model="time" min="2024-01-01T00:00" max="2025-12-31T17:00" step="3600" aria-label="站点预测起点"></label><label class="form-field">预测模型<select v-model="model" aria-label="站点预测模型"><option v-for="(name,id) in names" :value="id">{{ name }}</option></select></label><button class="button primary" :disabled="busy" @click="load"><ScanLine :size="15" />{{ busy?'正在加载':'加载观测与预测' }}<ArrowRight :size="14" /></button></div></section>
    <div v-if="busy" class="page-loader"><span class="spinner"></span>正在读取站点观测和真实模型输出…</div>
    <template v-else>
      <div class="two-column-grid"><section class="panel"><div class="panel-heading"><div><div class="section-kicker">STATION OBSERVATIONS</div><h2>监测站点的空间差异</h2></div><span class="subtle-tag">点击站点切换</span></div><Chart :option="mapOption" height="345px" label="监测站点 PM2.5 地图" @select="mapSelect" /><div class="panel-note">{{ snapshot?.time }} · 支持缩放；地图只显示该时刻有坐标和 PM₂.₅ 实测的记录。</div></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">STATION COMPARISON</div><h2>{{ city==='all'?'六城':cityNames[city] }}站点浓度</h2></div><span class="unit-label">μg/m³</span></div><div class="table-scroll station-ranking"><table><thead><tr><th>编号</th><th>监测站点</th><th class="numeric">PM₂.₅</th></tr></thead><tbody><tr v-for="s in snapshot?.stations" :key="s.station_id" :class="{'station-selected':s.station_id===stationId}" @click="stationId=s.station_id"><td><button class="station-link" :aria-label="`选择站点 ${s.station_id}`">{{ s.station_id }}</button></td><td>{{ s.name }}</td><td class="numeric strong-value">{{ fmt(s.pm25) }}</td></tr></tbody></table></div><div class="panel-note">缺测保留为空；站点停运或尚未启用的时段也可能无观测。</div></section></div>
      <div v-if="forecastError" class="error-box" role="alert">{{ forecastError }}</div>
      <section v-if="forecast" class="panel"><div class="panel-heading"><div><div class="section-kicker">CPU / GPU FORECAST REPLAY</div><h2>{{ selected?.name }}：未来六小时的两种预测</h2></div><button class="button text small" @click="download"><Download :size="14" />导出站点预测</button></div><div class="chart-legend"><span><i style="background:#719083"></i>历史观测</span><span><i style="background:#d29a59"></i>Spark 随机森林</span><span><i style="background:#176e59"></i>CUDA TCN</span><span><i style="background:#7198a4"></i>后续真实值</span><span class="legend-caption">起点 {{ fmt(forecast.current) }} μg/m³</span></div><Chart :option="forecastOption" height="330px" label="站点CPU和GPU六小时预测与真实值对比" /><div class="table-scroll"><table><thead><tr><th>目标时刻</th><th class="numeric">Spark RF</th><th class="numeric">CUDA TCN</th><th class="numeric">真实值</th><th>本次选用</th><th class="numeric">选用结果</th></tr></thead><tbody><tr v-for="p in forecast.points" :key="p.horizon"><td>{{ p.target.slice(5,16) }} <span class="hour-pill">+{{ p.horizon }}h</span></td><td class="numeric">{{ fmt(p.rf) }}</td><td class="numeric">{{ fmt(p.tcn72) }}</td><td class="numeric">{{ fmt(p.actual) }}</td><td>{{ names[p.model] }}</td><td class="numeric strong-value">{{ fmt(p.prediction) }}</td></tr></tbody></table></div><div class="panel-note">页面读取真实模型的批量输出；点击按钮不会重新训练。缺失真实值不参与误差计算。</div></section>
      <div class="two-column-grid"><section class="panel"><div class="panel-heading"><div><div class="section-kicker">METEOROLOGICAL HISTORY</div><h2>过去 72 小时的气象变化</h2></div><select v-model="weather" class="compact-select" aria-label="站点历史气象变量"><option v-for="(info,key) in weatherInfo" :value="key">{{ info[0] }}</option></select></div><Chart :option="weatherOption" height="255px" label="预测起点之前72小时气象曲线" /><div class="panel-note">ERA5 城市代表坐标的格点数据，由同城站点共享；不是每个空气站的气象实测。</div></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">DAILY STATION TREND</div><h2>{{ selected?.name }}的逐日变化</h2></div><select v-model="year" @change="load" class="compact-select" aria-label="站点趋势年份"><option v-for="y in [2025,2024,2023,2022]" :value="String(y)">{{ y }} 年</option></select></div><Chart :option="trendOption" height="255px" label="所选监测站点日均PM2.5曲线" /><div class="panel-note">按有效小时计算日均值，全年无观测时保留空值。</div></section></div>
    </template>
    <section class="panel"><div class="panel-heading"><div><div class="section-kicker">SAME COHORT EVALUATION</div><h2>在同一批站点小时上比较模型</h2></div><div class="station-evaluation-controls"><select v-model="scope" class="compact-select" aria-label="站点评估范围"><option value="beijing">北京站点</option><option value="all">全部六城站点</option></select><select v-model="split" class="compact-select" aria-label="站点评估期间"><option value="test">2025 独立测试</option><option value="validation">2024 验证</option></select></div></div><div class="two-column-grid station-inner-grid"><Chart :option="errorOption" height="295px" label="站点持续基线随机森林和GPU模型各时长RMSE对比" /><Chart :option="ablationOption" height="295px" label="当前气象和72小时气象历史的六小时预测消融对比" /></div><div class="table-scroll"><table><thead><tr><th>预测时长</th><th>模型</th><th class="numeric">MAE</th><th class="numeric">RMSE</th><th class="numeric">R²</th><th class="numeric">有效样本数</th></tr></thead><tbody><template v-for="h in [1,3,6]"><tr v-for="id in ['persistence','rf','tcn72']" :key="`${h}-${id}`"><td>+{{ h }} h</td><td>{{ names[id] }}</td><td class="numeric">{{ fmt(metric(id,h)?.mae,2) }}</td><td class="numeric strong-value">{{ fmt(metric(id,h)?.rmse,2) }}</td><td class="numeric">{{ fmt(metric(id,h)?.r2,3) }}</td><td class="numeric">{{ fmt(metric(id,h)?.n,0) }}</td></tr></template></tbody></table></div><div class="panel-note">每个时长使用相同有效评估样本。推荐结果只看 2024 年北京站点验证 RMSE；GPU 模型的输入表达为完整序列，RF 使用滞后与滚动摘要。</div></section>
    <section class="panel"><div class="panel-heading"><div><div class="section-kicker">CUDA TRAINING EVIDENCE</div><h2>显卡确实参与了训练</h2></div><span class="subtle-tag">{{ gpu?.device }}</span></div><div class="station-gpu-grid"><div class="station-proof"><p><strong>{{ fmt(gpu?.train_origins,0) }}</strong><span>真实训练起点</span></p><p><strong>{{ fmt(gpu?.peak_torch_memory_mib,0) }} MiB</strong><span>PyTorch 峰值张量显存</span></p><p><strong>{{ gpu?.best_epoch }} / {{ gpu?.epochs.length }}</strong><span>最佳 / 实际训练轮次</span></p><p><strong>{{ fmt(gpu?.elapsed_seconds/60,1) }} 分钟</strong><span>训练及最终推理耗时</span></p><div class="panel-note">PyTorch {{ gpu?.pytorch }} · CUDA {{ gpu?.cuda_runtime }}。显存和利用率为实际采样；模型训练完成后 GPU 会空闲。</div></div><Chart :option="trainingOption" height="240px" label="GPU模型各训练轮次的验证集六小时RMSE" /></div></section>
    <div class="method-note"><Info :size="16" /><p>新增原始归档 {{ fmt(meta.summary.raw_archive_bytes/1e9,2) }} GB，{{ fmt(meta.summary.source_file_count,0) }} 份全国逐站小时文件。Spark 提取原六城站点、去重并构建小时网格，保留历史站点身份；气象历史与区域污染信息仅取预测起点及之前。历史再分析回测尚不能代表真实在线预报表现。<a href="https://github.com/HeQinWill/CNEMC" target="_blank" rel="noreferrer">查看归档来源 ↗</a></p></div>
  </template>
</template>
